'use strict';
// Feature module: persistent drafts, local three-model chat, sources and backup status.
navItems.splice(1,0,['chat','KI-Chat','spark']);
navItems.splice(navItems.length-1,0,['assessments','Bescheide','mail'],['knowledge','Rechtsquellen','file'],['safety','Sicherung','download']);
Object.assign(app,{chatItems:[],chatYear:null,legal:null,recoveredFile:null,recoveredReceiptFile:null,transactionReceiptFile:null,draftQueue:Promise.resolve(),suppressDraft:false,draftRevision:0});
const stamp = value => value ? new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(value)) : 'Noch nicht vorhanden';
const scopeNames={business:'Betrieblich',private:'Privat',mixed:'Gemischt',unknown:'Ungeklärt',transfer:'Eigenübertrag'};
const baseRender=render,baseSettings=settingsView,baseAction=action,baseDocumentForm=documentForm,baseTransactionForm=transactionForm,baseTaskForm=taskForm,baseClose=closeModal;
const baseOverview=overviewView,baseTransactions=transactionsView,baseTasks=tasksView;

function nextTaskDate(t){return [t.prepare_on,t.due_on].filter(Boolean).sort()[0]||'9999';}
overviewView=function(){
 const all=app.data.tasks.filter(t=>t.status!=='done').sort((a,b)=>nextTaskDate(a).localeCompare(nextTaskDate(b))||a.title.localeCompare(b.title));
 const overdue=all.filter(t=>nextTaskDate(t)<localDate()),urgent=overdue[0],s=app.data.storage||{},sum=totals(txForYear());
 const recent=[...baseTxForYear()].sort((a,b)=>b.paid_on.localeCompare(a.paid_on)).slice(0,5);
 const filingOpen=app.data.settings.filing_2025!=='submitted';
 return `<div class="home-calm">${head('Dein Überblick.','YouTube · Twitch · Privat')}
 ${s.backup?.error?`<div class="home-alert" role="alert"><div><strong>Sicherung prüfen</strong><p>${esc(s.backup.error)}</p></div>${button('Öffnen','navigate','','small','data-view="safety"')}</div>`:''}
 ${urgent?`<div class="home-alert"><div><strong>${overdue.length} offene Termine in der Vergangenheit</strong><p>${esc(urgent.title)} · ${fmtDate(nextTaskDate(urgent))}${urgent.due_confirmed?'':' · Frist prüfen'}</p></div>${button('Prüfen','edit-task','','small',`data-id="${urgent.id}"`)}</div>`:filingOpen?`<div class="home-alert"><div><strong>Abgabestand 2025 klären</strong><p>Individuelle Frist und bisherigen Bearbeitungsstand prüfen.</p></div>${button('Prüfen','startcheck','','small')}</div>`:''}
 <section class="home-actions" aria-label="Was möchtest du erledigen?">
 <button class="home-action home-action-primary" data-action="bank-import">${icon('upload')}<span><strong>Auszug importieren</strong><small>CSV oder PDF einlesen</small></span>${icon('arrow')}</button>
 <button class="home-action" data-action="navigate" data-view="inbox">${icon('check')}<span><strong>Belege zuordnen</strong><small>Monat für Monat erledigen</small></span>${icon('arrow')}</button>
 <button class="home-action" data-action="navigate" data-view="chat">${icon('spark')}<span><strong>KI fragen</strong><small>Unterlagen und Fragen klären</small></span>${icon('arrow')}</button>
 </section>
 <section class="panel home-year"><div class="panel-header"><h2>Dein Jahr ${app.year}</h2><button class="text-link" data-action="show-transactions">Buchungen ansehen</button></div><div class="home-numbers"><div><span>Betriebliche Einnahmen</span><strong>${money(sum.income)}</strong></div><div><span>Betriebliche Ausgaben</span><strong>${money(sum.expense)}</strong></div><button data-action="navigate" data-view="documents"><span>Dokumente</span><strong>${docsForYear().length}</strong></button></div><p class="home-caption">Erfasste betriebliche Zahlungen, keine fertige EÜR. Private, gemischte und ungeklärte Zahlungen sowie Eigenüberträge sind nicht enthalten.</p></section>
 <section class="panel home-next"><div class="panel-header"><div><h2>Als Nächstes</h2><span class="small muted">Offene Aufgaben aus allen Arbeitsjahren</span></div><button class="text-link" data-action="navigate" data-view="tasks">Aufgaben ansehen</button></div><div class="panel-body">${all.length?all.slice(0,3).map(t=>`<div class="home-task">${taskRow(t)}<span class="home-task-year">Arbeitsjahr ${t.year}</span></div>`).join(''):`<p class="small muted">Keine offenen Aufgaben erfasst.</p><div class="actions section-gap">${button('Startaufgaben ergänzen','seed-tasks','plus','small')}${button('Eigene Aufgabe','new-task','','ghost small')}</div>`}</div></section>
 ${draftBanner()}
 <details class="home-details"><summary>Weitere Hinweise & Einrichtung${app.data.assessments?.available?' · Bescheide zur Übernahme bereit':filingOpen?' · Abgabestand 2025 offen':''}</summary><div class="home-details-body"><p>Steuerstatus, Bearbeitungsstand 2025 und persönliche Angaben findest du in den Einstellungen.</p><div class="actions">${button('Bescheide 2024','navigate','','small','data-view="assessments"')}${button('Einstellungen','startcheck','','small')}${button('Konten & Import','navigate','','small','data-view="banking"')}${button('Sicherung prüfen','navigate','','small','data-view="safety"')}</div>${s.last_saved_at?`<p class="small muted">Zuletzt gespeichert: ${stamp(s.last_saved_at)}</p>`:''}</div></details>
 <details class="home-details"><summary>Letzte Zahlungen · ${app.year}</summary>${recent.length?transactionTable(recent):'<p class="home-details-body muted small">Noch keine Zahlungen erfasst.</p>'}</details></div>`;
};

// Business overview never mixes private payments into the business totals.
const baseTxForYear=txForYear;
txForYear=()=>baseTxForYear().filter(t=>(t.scope||'business')==='business');
transactionsView=function(){const scope=app.scopeFilter||'business',all=baseTxForYear();
  const old=txForYear;txForYear=()=>all.filter(t=>scope==='all'||(t.scope||'business')===scope);
  let html;try{html=baseTransactions();}finally{txForYear=old;}
  return `<div class="scope-tabs" role="group" aria-label="Bereich">${[['business','Betrieblich'],['private','Privat'],['mixed','Gemischt'],['unknown','Ungeklärt'],['transfer','Eigenüberträge'],['all','Alle Zahlungen']].map(([v,l])=>button(l,'scope-filter','',scope===v?'selected':'',`data-value="${v}"`)).join('')}</div>`+html;};
tasksView=function(){return baseTasks()+`<details class="home-details"><summary>Hilfe beim Start</summary><div class="home-details-body"><p class="small muted">Vorschläge ohne erfundene Frist. Bereits vorhandene Aufgaben werden nicht doppelt angelegt.</p><div class="actions section-gap">${button('Startaufgaben ergänzen','seed-tasks','plus','small')}</div></div></details>`;};

function draftBanner(){const drafts=app.data.drafts||[];return drafts.length?`<details class="home-details draft-banner"><summary>${drafts.length} gespeicherte Entwürfe · Fortsetzen</summary><div class="actions home-details-body">${drafts.map(d=>button(esc(d.title||d.key),'resume-draft','edit','small',`data-key="${esc(d.key)}"`)).join('')}</div></details>`:'';}
function chatView(){return head('Dein Steuer-Gedächtnis.','Gespräche bleiben gespeichert. Die KI holt passende Fakten und Quellen aus deiner Ablage.')+
  draftBanner()+`<div class="chat-layout"><section class="panel chat-panel"><div class="panel-header"><h2>Dein Gespräch</h2><span class="tag">3 lokale Modelle</span></div><div id="chat-history" class="chat-history">${chatHistory()}</div><form id="chat-form" class="chat-compose"><div class="form-result" role="alert"></div>${textarea('Was möchtest du klären?','question','','required maxlength="12000" placeholder="Welche Belege fehlen für April 2025? Was muss ich für meinen Umzug erledigen?"')}<details class="chat-attachments"><summary>Unterlagen mitgeben <span>optional · bis zu 3</span></summary><div class="field"><label for="chat-documents">Dokumente auswählen</label><select id="chat-documents" name="document_ids" multiple size="3">${app.data.documents.map(d=>`<option value="${d.id}">${d.year} · ${esc(d.title)}</option>`).join('')}</select></div></details><div class="compose-footer"><span class="save-state" role="status">Die Frage wird als Entwurf gespeichert.</span><button type="submit" class="btn primary">${icon('spark')}Frage prüfen lassen</button></div></form></section><aside class="stack"><section class="panel"><div class="panel-header"><h2>Deine drei Perspektiven</h2></div><div class="panel-body"><div class="role-row"><span>01</span><div><strong>Arbeiter</strong><p>Qwen liest und ordnet.</p></div></div><div class="role-row"><span>02</span><div><strong>Prüfer</strong><p>Gemma beurteilt denselben Fall ohne Qwens Antwort.</p></div></div><div class="role-row"><span>03</span><div><strong>Koordinator</strong><p>GPT-OSS fasst zusammen und hält offene Punkte fest.</p></div></div><p class="small muted">Nacheinander auf deiner GPU. Eine Übereinstimmung ist keine steuerliche Freigabe.</p></div></section><section class="panel"><div class="panel-header"><h2>Gesicherte Fakten · ${app.year}</h2>${button('Fakt ergänzen','new-fact','plus','small')}</div><div class="panel-body">${factsMarkup()}</div></section></aside></div>`;}
function factsMarkup(){const f=(app.data.facts||[]).filter(f=>f.year===app.year&&f.status!=='superseded');return f.length?f.map(x=>`<button class="memory-card" data-action="edit-fact" data-id="${x.id}"><strong>${esc(x.title)}</strong><span>${esc(x.value)}</span><small>${x.status==='confirmed'?'Von dir geprüft':'Noch offen'} · ${esc(x.source_note)}</small></button>`).join(''):'<p class="small muted">Dauerhafte Angaben mit Steuerjahr und Quelle festhalten. Die KI verändert sie nicht selbst.</p>';}
function answerMarkup(answer){if(!answer)return '';return `<div class="answer-text">${esc(answer.answer||answer.summary||'')}</div>${answer.conflicts?.length?`<div class="answer-warning"><strong>Abweichungen offen</strong><ul>${answer.conflicts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${answer.missing?.length?`<div class="answer-missing"><strong>Was noch fehlt</strong><ul>${answer.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${answer.citations?.length?`<details class="source-details"><summary>Fundstellen · ${answer.citations.length}</summary>${answer.citations.map(c=>`<div class="quote"><strong>${esc(c.title)}</strong><p>${esc(c.quote)}</p>${c.url&&/^https:\/\//.test(c.url)?`<a href="${esc(c.url)}" target="_blank" rel="noreferrer">Amtliche Quelle öffnen ↗</a>`:''}${c.year_checked===false?'<p class="small">Zeitliche Anwendbarkeit noch nicht bestätigt.</p>':''}</div>`).join('')}</details>`:''}`;}
function chatHistory(){const items=app.chatYear===app.year?app.chatItems:[];if(!items.length)return `<div class="chat-empty"><span class="chat-orb">✦</span><h3>Ein klarer nächster Schritt.</h3><p>Beginne mit „Was fehlt noch für ${app.year}?“<br>Die KI sieht erfasste Zahlungen, Aufgaben und ausgewählte Quellen.</p></div>`;
 return items.map(c=>`<article class="chat-turn"><div class="user-bubble">${esc(c.question)}</div><div class="chat-meta">${stamp(c.created_at)} · Arbeitsjahr ${c.year}</div><div class="assistant-bubble">${['queued','running'].includes(c.state)?`<p class="progress-label"><span class="spinner"></span>${esc(c.progress||'Auswertung startet …')}</p>`:c.state==='error'?`<div class="form-error">${esc(c.error)}</div>`:answerMarkup(c.coordinator_json)}${c.context_stale?'<p class="answer-warning">Eine verwendete Buchung, Profilangabe oder Dokumentquelle wurde geändert. Bitte neu fragen.</p>':''}${c.coordinator_json?.tasks?.length?`<div class="actions section-gap">${c.coordinator_json.tasks.map((t,i)=>button(esc(t.title),'chat-task','plus','small',`data-id="${c.id}" data-index="${i}"`)).join('')}</div>`:''}<details class="source-details"><summary>Einzelauswertungen & Kontext</summary><h3>Arbeiter</h3>${answerMarkup(c.worker_json)}<h3>Unabhängiger Prüfer</h3>${answerMarkup(c.reviewer_json)}<p class="small muted">${esc(c.coverage)}</p><p class="small muted">${c.sources.map(s=>esc(s.title)+(s.excerpt?' (Auszug)':'')).join(' · ')||'Keine passende Dokumentquelle ausgewählt.'}</p></details></div></article>`).join('');}
async function loadChat(){const year=app.year,revision=(app.chatLoadRevision||0)+1;app.chatLoadRevision=revision;try{const items=await api('/api/chat?year='+year);if(app.year!==year||app.chatLoadRevision!==revision)return;app.chatItems=items;app.chatYear=year;if($('#chat-history'))$('#chat-history').innerHTML=chatHistory();clearTimeout(app.chatPoll);if(items.some(c=>['queued','running'].includes(c.state)))app.chatPoll=setTimeout(loadChat,2500);}catch(e){if(app.chatLoadRevision===revision)toast(e.message,true);}}

function knowledgeView(){const data=app.legal;return head('Wissen mit Herkunft.','Gespeicherte Quellen stehen deiner KI zum Nachschlagen zur Verfügung.',button('Quellen aktualisieren','update-legal','download','primary'))+
 `<section class="panel"><div class="panel-body legal-status" id="legal-status">${data?legalStatus(data):'Quellen werden geladen …'}</div></section>
 <details class="home-details"><summary>Warum ist die zeitliche Anwendung noch offen?</summary><div class="home-details-body"><p>Ein erfolgreicher Download macht den Text für die KI lesbar. Du musst keine Quelle einzeln öffnen oder freigeben.</p><p>Die amtlichen Seiten liefern ihre aktuelle Fassung. Für dein Arbeitsjahr ${app.year} können frühere Regeln und Übergangsvorschriften gelten. Das Abrufdatum beweist diese Gültigkeit nicht. Deshalb bleibt die Anwendung im konkreten Steuerfall gesondert zu prüfen.</p><p>Die Jahreszuordnung ist optional und für eine belegte Prüfung gedacht. Bitte nicht pauschal alle Gesetze bestätigen. Das Archiv enthält ausgewählte Quellen, nicht das vollständige Steuerrecht.</p></div></details>
 <div class="source-grid">${data?data.catalog.map(s=>{const versions=data.versions.filter(v=>v.source_id===s.id),v=versions.find(v=>v.source_type!=='redaktioneller Hinweis')||versions[0],downloaded=v&&v.source_type!=='redaktioneller Hinweis',check=data.checks.find(c=>c.source_id===s.id);return `<section class="panel source-card"><div class="panel-header"><h2>${esc(s.title)}</h2><span class="tag ${downloaded?'green':'amber'}">${downloaded?'Gespeichert':v?'Nur Starthinweis':'Noch nicht geladen'}</span></div><div class="panel-body"><p class="small muted">${downloaded?`${v.units} Abschnitte · gespeichert ${stamp(v.retrieved_at)}`:v?'Vorbereitete Zusammenfassung vorhanden. Amtlichen Originaltext noch laden.':'Amtlichen Originaltext einmal laden.'}</p>${downloaded?`<p class="small muted">${v.reviewed?`Jahreszuordnung von dir erfasst: ${v.valid_from}–${v.valid_to}`:'Zeitliche Anwendung im Steuerfall noch offen.'}</p>`:''}${check?.checked_at?`<p class="small muted">Letzter erfolgreicher Abruf: ${stamp(check.checked_at)}</p>`:''}${check?.error?`<p class="form-error">${esc(check.error)}</p>`:''}<div class="actions section-gap"><a class="btn small" href="${esc(s.web_url||s.url)}" target="_blank" rel="noreferrer">Webseite ansehen ↗</a>${button(downloaded?'Erneut laden':'Quelle laden','retry-legal','download','small',`data-id="${s.id}"`)}</div>${downloaded?`<details class="source-details"><summary>Jahreszuordnung · optional</summary><p class="small muted">Nur nach Prüfung der maßgeblichen Fassung und Übergangsregeln erfassen.</p>${button('Jahreszuordnung bearbeiten','review-law','edit','small',`data-id="${v.id}"`)}</details>`:''}${versions.length>1?`<p class="small muted">${versions.length} Fassungen erhalten.</p>`:''}</div></section>`;}).join(''):''}</div>
 <section class="panel"><div class="panel-header"><h2>Im lokalen Archiv nachschlagen</h2></div><form id="law-search-form" class="panel-body">${field('Suchbegriff','q','','search','required placeholder="Kleinunternehmer, Frist, Umzug …"')}<button class="btn" type="submit">Suchen</button><div class="form-result" role="status"></div></form><div id="law-results" class="panel-body"></div></section>`;}
function legalStatus(data){const status=data.status,errors=data.checks.filter(c=>c.error),count=new Set(data.versions.filter(v=>v.source_type!=='redaktioneller Hinweis').map(v=>v.source_id)).size;return `<strong>${count} von ${data.catalog.length} Originalquellen gespeichert</strong><p>${status.running?'<span class="spinner"></span> ':''}${esc(status.progress||'Gespeicherte Quellen bleiben auch nach einem Neustart verfügbar.')}</p>${errors.length?`<div class="legal-errors" role="status"><strong>${errors.length===1?'Eine Quelle benötigt':'Einige Quellen benötigen'} einen neuen Abruf</strong><ul>${errors.map(c=>`<li>${esc(c.error)}</li>`).join('')}</ul>${button('Fehlgeschlagene erneut laden','retry-failed-legal','download','small')}</div>`:count?'<p class="small muted">Du musst die gespeicherten Quellen nicht einzeln öffnen.</p>':'<p class="small muted">Oben einmal „Quellen aktualisieren“ anklicken.</p>'}`;}
async function loadLegal(){app.legal=await api('/api/legal');if(app.view==='knowledge'&&!$('#modal').open){const search=$('#law-search-form [name="q"]')?.value;render();if(search&&$('#law-search-form [name="q"]'))$('#law-search-form [name="q"]').value=search;}clearTimeout(app.legalPoll);if(app.legal.status.running)app.legalPoll=setTimeout(loadLegal,3500);}

function safetyView(){const s=app.data.storage||{},cfg=app.data.settings;return head('Gut aufgehoben.','Gespeicherte Daten und Sicherungen auf einen Blick.',button('Jetzt sichern','snapshot','download','primary'))+
 `<div class="stat-grid storage-stats">${stat('Zuletzt gespeichert',s.last_saved_at?stamp(s.last_saved_at):'Noch kein Eintrag','Erfolgreiche Änderung in der Datenbank','check')}${stat('Lokale Sicherung',s.last_snapshot?stamp(s.last_snapshot):'Noch offen','Automatisch bei Änderungen, spätestens alle 15 Minuten solange geöffnet','download')}${stat('Zusätzliche Kopie',s.external_snapshot?stamp(s.external_snapshot):'Noch offen','Datum der letzten bestätigten Kopie','file')}${stat('Entwürfe',s.draft_count||0,'Eingaben und ausgewählte Dateien','edit')}</div>
 ${s.backup?.error?`<div class="banner warn"><strong>${esc(s.backup.error)}</strong></div>`:''}<div class="settings-grid"><section class="panel"><div class="panel-header"><h2>Deine feste Datenablage</h2></div><div class="panel-body"><p class="path-display">${esc(s.data_path)}</p><p class="small muted">Neue Programmversionen verwenden denselben Ort. Originale, Chat, Aufgaben, Rechtsquellen und Entwürfe sind Bestandteil der Sicherung.</p><div class="divider"></div><p class="small muted">Lokale Sicherungen:</p><p class="path-display">${esc(s.snapshot_path)}</p>${button('ZIP-Sicherung herunterladen','backup','download')}</div></section><section class="panel"><div class="panel-header"><h2>Kopie auf einem zweiten Datenträger</h2></div><form id="backup-settings-form" class="panel-body">${field('Vorhandener Sicherungsordner','backup_directory',cfg.backup_directory,'text','placeholder="E:\\Steuer-Sicherungen"')}<p class="small muted settings-note">Ordner zuerst im Explorer erstellen. Bitte einen anderen physischen Datenträger wählen. Ist er nicht angeschlossen, erscheint ein Fehler. Sicherungen sind unverschlüsselt; Datenträger schützen.</p><button type="submit" class="btn primary">Ordner speichern</button><div class="form-result" role="status"></div></form></section><section class="panel"><div class="panel-header"><h2>Eine Sicherung prüfen</h2></div><form id="restore-check-form" class="panel-body"><div class="field"><label for="restore-file">Steuerstudio-Sicherung (ZIP, bis 20 MB)</label><input id="restore-file" type="file" accept=".zip" required></div><button type="submit" class="btn">Datenbank & Originale prüfen</button><div class="form-result" role="status"></div><p class="small muted settings-note">Die Prüfung überschreibt nichts. Für die tatsächliche Wiederherstellung oder größere Dateien: Programm beenden und WIEDERHERSTELLEN_WINDOWS.bat starten. Es wird ein neuer Ordner angelegt.</p></form></section><section class="panel"><div class="panel-header"><h2>Dein kurzer Neustart-Test</h2></div><div class="panel-body"><ol class="plain-steps"><li>Einen Beleg und eine Zahlung speichern.</li><li>Ein zweites Formular nur teilweise ausfüllen und „Entwurf gespeichert“ abwarten.</li><li>Programm schließen und neu öffnen.</li><li>Beleg, Zahlung und Entwurf wieder öffnen.</li><li>Eine Sicherung erstellen und prüfen.</li></ol><p class="small muted">Danach erst größere Mengen erfassen. Ein Backup auf derselben SSD schützt nicht vor einem Defekt dieser SSD.</p></div></section></div>`;}

settingsView=function(){let html=baseSettings();html=html.replace('Zwei Leser werten denselben Dokumenttext getrennt aus. Du prüfst Vorschläge vor der Übernahme.','Arbeiter und Prüfer lesen unabhängig. Der Koordinator hält Ergebnisse und offene Punkte fest. Alle drei laufen nacheinander.').replace('Notizen werden gespeichert, in dieser Version aber nicht automatisch an die Dokumenten-Lesehilfe übergeben.','Notizen fließen als begrenzter Auszug in den Chat ein. Wichtige Fakten bitte zusätzlich mit Arbeitsjahr und Quelle festhalten.');
 const insertAt='<button class="btn primary" type="submit">Modelle speichern</button>';
 html=html.replace(insertAt,select('Koordinator','coordinator_model',[...new Set([app.data.settings.coordinator_model,...app.models].filter(Boolean))],app.data.settings.coordinator_model)+select('Kontextfenster (bei Speicherproblemen klein lassen)','num_ctx',[[8192,'8.192 · Startwert'],[12288,'12.288 · mehr Kontext'],[16384,'16.384 · mehr Speicherbedarf']],app.data.settings.num_ctx||8192)+insertAt);
 html=html.replace('Keine kostenpflichtige API angebunden. Keine Rechtsrecherche oder automatische Steuerfreigabe. Dasselbe Modell in beiden Rollen ist keine unabhängige fachliche Kontrolle.','Nur lokale Ollama-Modelle. Amtliche Quellen separat im Quellenarchiv abrufen. Steuerliche Freigabe und ELSTER-Übermittlung sind nicht enthalten.');
 const obsolete=html.indexOf('<section class="panel wide-note"><div class="panel-header"><h2>Deine Daten gehören dir.');if(obsolete>=0)html=html.slice(0,obsolete)+'</div>';
 return html+`<div class="settings-grid section-gap"><details class="panel settings-section"><summary>Umzug & Finanzamt <span class="tag">Stuttgart → Kuppenheim</span></summary><form id="move-form" class="panel-body">${field('Bisheriges Finanzamt, genaue Dienststelle','current_office',app.data.settings.current_office)}${field('Bisherige Anschrift','current_address',app.data.settings.current_address)}${field('Bisherige Steuernummer','tax_number_current',app.data.settings.tax_number_current)}${field('Geplante neue Anschrift','future_address',app.data.settings.future_address)}${field('Tatsächliches Umzugsdatum','move_on',app.data.settings.move_on,'date')}${field('Neues Finanzamt','future_office',app.data.settings.future_office)}${field('Neue Steuernummer, sobald mitgeteilt','tax_number_future',app.data.settings.tax_number_future)}<label class="check"><input name="move_confirmed" type="checkbox"${app.data.settings.move_confirmed?' checked':''}>Umzug erfolgt; Zuständigkeitswechsel anhand einer Mitteilung geprüft.</label><p class="small muted settings-note">Keine automatische Meldung. Neue Anschrift über das ELSTER-Formular mitteilen und Übermittlungsprotokoll ablegen.</p><button class="btn primary" type="submit">Umzugsdaten speichern</button><div class="form-result" role="status"></div></form></details><details class="panel settings-section"><summary>Rechtsquellen automatisch aktualisieren</summary><form id="legal-settings-form" class="panel-body"><label class="check"><input name="auto_legal_update" type="checkbox"${app.data.settings.auto_legal_update?' checked':''}>Amtliche Quellen einmal täglich abrufen, solange das Steuerstudio läuft.</label><p class="small muted settings-note">Es werden nur feste öffentliche Quellenadressen abgerufen. Belege und Chat gehen nicht ins Internet. Geänderte Fassungen bleiben getrennt; ihre Anwendbarkeit auf das Steuerjahr ist gesondert zu prüfen.</p><button class="btn" type="submit">Einstellung speichern</button><div class="form-result" role="status"></div></form></details></div>`;};

function assessmentsView(){const state=app.data.assessments||{cases:[]};return head('Deine Bescheide.','Alle Jahre · Originale, übertragene Werte und offene Prüfungen.').replace(`DEIN ARBEITSJAHR ${app.year}`,'ALLE ARBEITSJAHRE')+
 (state.available?`<section class="panel section-gap"><div class="panel-header"><h2>Bescheide 2024 übernehmen</h2><span class="tag blue">Vorbereitet</span></div><div class="panel-body"><p>Die fünf PDFs vom 24.09.2026 und deine Beratermitteilung sind in diesem Update enthalten. Einmal übernehmen, um die Originale, abgelesene Werte und fünf Aufgaben dauerhaft abzulegen.</p><p class="small muted section-gap">Auszüge wurden am Seitenbild abgeglichen. Die fachliche Prüfung bleibt offen. Bestehende Buchungen und Steuerstatus werden nicht geändert; es entstehen keine automatischen Zahlungen.</p>${button('In meine Ablage übernehmen','import-assessments','download','primary')}</div></section>`:'')+
 state.cases.map(c=>`<section class="panel section-gap"><div class="panel-header"><div><h2>${esc(c.title)}</h2><span class="small muted">Übernommen ${stamp(c.imported_at)}</span></div><span class="tag amber">Prüfung offen</span></div><div class="panel-body">${c.source_changed?'<div class="form-error">Eine Quelle wurde nach der Übernahme geändert oder archiviert. Übertragene Werte und Prüfstatus erneut am Original abgleichen.</div>':''}<p>${esc(c.summary)}</p><details class="home-details section-gap" open><summary>Was du jetzt tun solltest</summary><div class="home-details-body">${c.tasks.length?c.tasks.map(taskRow).join(''):'<p>Keine zugehörigen Aufgaben in der Arbeitsansicht.</p>'}</div></details><details class="home-details"><summary>Werte und Einordnung · ${c.facts.length} Angaben</summary><div class="home-details-body">${c.facts.map(f=>`<article class="fact"><button class="table-button" data-action="edit-fact" data-id="${f.id}">${esc(f.title)}</button><span class="tag ${f.status==='confirmed'?'green':'amber'}">${f.year} · ${f.status==='confirmed'?'Von dir geprüft':f.status==='superseded'?'Überholt':'Prüfung offen'}</span><p>${esc(f.value)}</p><p class="small muted">${esc(f.source_note)}</p></article>`).join('')}</div></details><details class="home-details"><summary>Originale und Auszüge öffnen · ${c.documents.length}</summary><div class="home-details-body actions">${c.documents.map(d=>button(esc(d.title),'open-document','file','small',`data-id="${d.id}"`)).join('')}</div></details><p class="small muted">Gesetzliche Fristen sind noch nicht bestätigt. Vorbereitungstermine sind interne Aufgaben, keine vom Finanzamt gesetzten Fristen. Verlustvorträge sind keine Auszahlung.</p></div></section>`).join('')+(!state.available&&!state.cases.length?empty('Noch keine Bescheide übernommen.','Finanzamtsschreiben kannst du unter Dokumente hinzufügen.','mail'):'' );}

const sourceAnswerMarkup=answerMarkup;
answerMarkup=function(answer){if(!answer)return '';return sourceAnswerMarkup(answer)+(answer.evidence_warnings?.length?`<div class="answer-warning"><strong>Quellenprüfung</strong><ul>${answer.evidence_warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:'')+(answer.citations?.some(c=>/^[DTFKCP]:/.test(c.source_id||''))?`<div class="actions section-gap citation-links">${[...new Map(answer.citations.filter(c=>/^[DTFKCP]:/.test(c.source_id||'')).map(c=>[c.source_id,c])).values()].map(c=>button('Quelle ansehen: '+esc(c.title),'cited-source','file','small',`data-source="${esc(c.source_id)}"`)).join('')}</div>`:'');};

render=function(){if(!app.data)return;
 if(['chat','knowledge','safety','assessments'].includes(app.view)){
   const v=app.view;app.view='overview';baseRender();app.view=v;
   $('#main').innerHTML=({chat:chatView,knowledge:knowledgeView,safety:safetyView,assessments:assessmentsView}[v])();
   $('#breadcrumb-current').textContent=navItems.find(n=>n[0]===v)[1];
   document.querySelectorAll('#nav .nav-item').forEach(a=>{const active=a.dataset.view===v;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
   if(['knowledge','safety','assessments'].includes(v))$('#nav .nav-more').open=true;
   if(v==='chat'&&app.chatYear!==app.year)loadChat();
   if(v==='knowledge'&&!app.legal)loadLegal().catch(e=>toast(e.message,true));
 }else baseRender();
 const el=$('#save-indicator');if(el){el.textContent=app.data.storage?.last_saved_at?'Lokal gespeichert':'Lokale Ablage';el.title=app.data.storage?.last_saved_at?'Zuletzt gespeichert: '+stamp(app.data.storage.last_saved_at):'Noch keine Änderung gespeichert';}
};

function addSaveState(form){if(form&&!$('.save-state',form)){const el=document.createElement('p');el.className='save-state';el.setAttribute('role','status');el.textContent='Eingaben werden automatisch als Entwurf gespeichert.';$('.modal-body',form)?.prepend(el);}}
documentForm=function(...args){app.recoveredFile=null;baseDocumentForm(...args);$('#document-form')._file=args[1]||null;addSaveState($('#document-form'));if(args[1])queueDraft($('#document-form'));};
const paymentMethodNames=[['unknown','Zahlungsart noch ungeklärt'],['bank','Bank / Karte / Überweisung'],['cash','Bar bezahlt']];
const cashSourceNames=[['private_wallet','Aus privatem Portemonnaie'],['business_cash','Aus Geschäftskasse'],['unknown','Bargeldquelle noch ungeklärt']];
const expenseKindNames=[['standard','Normale Ausgabe'],['video_purchase','Einkauf für ein Video'],['business_meal','Geschäftsessen / Bewirtung'],['other','Sonstiger Sonderfall']];
const detailWrap=(klass,html)=>`<div class="${klass}">${html}</div>`;
function syncScopeDetails(form){
  const scope=form?.querySelector('[name=scope]')?.value||'business';
  const label=form?.querySelector('.data-checked-label');
  if(!label)return;
  label.textContent=scope==='private'?'Betrag, Zahlungsdatum und private Zuordnung geprüft. Für diese Zahlung ist kein separater Betriebsbeleg erforderlich.':scope==='transfer'?'Betrag, Zahlungsdatum und Eigenübertrag geprüft. Ein Eigenübertrag ist kein Aufwand und benötigt keinen Beleg.':scope==='unknown'?'Betrag und Zahlungsdatum geprüft. Bereich und Belegpflicht noch klären.':'Betrag, Zahlungsdatum und Beleg am Original geprüft. Das bestätigt noch keine steuerliche Absetzbarkeit.';
}
function syncPaymentDetails(form){
  const method=form?.querySelector('[name=payment_method]')?.value||'unknown';
  const kind=form?.querySelector('[name=expense_kind]')?.value||'standard';
  const special=form?.querySelector('.context-details');
  form?.querySelector('.cash-source-wrap')?.classList.toggle('cash-details-hidden',method!=='cash');
  form?.querySelector('.cash-explanation')?.classList.toggle('cash-details-hidden',method!=='cash');
  form?.querySelector('.video-purpose-wrap')?.classList.toggle('cash-details-hidden',kind!=='video_purchase');
  form?.querySelector('.meal-details-wrap')?.classList.toggle('cash-details-hidden',kind!=='business_meal');
  if(special&&(method==='cash'||kind!=='standard'))special.open=true;
  syncScopeDetails(form);
}
transactionForm=function(...args){baseTransactionForm(...args);const form=$('#transaction-form'),t=app.data.transactions.find(t=>t.id===args[0])||{};
  app.transactionReceiptFile=null;app.recoveredReceiptFile=null;form._receiptFile=null;form._recoveredReceiptFile=null;
  const method=t.payment_method|| (t.account_id?'bank':'unknown');
  const advancedDetails=`<details class=\"advanced-details\"><summary>Weitere Steuerangaben (optional)</summary>${field('Betrieblicher Anteil in % (ungeklärt: leer)','business_percent',t.business_percent??'','number','min=\"0\" max=\"100\" step=\"1\"')}${select('Umsatzsteuerliche Behandlung (vorläufig)','vat_treatment',[['unknown','Noch zu prüfen'],['domestic','Inländischer Umsatz'],['small','Kleinunternehmer – belegt'],['reverse_charge','Reverse Charge – zu prüfen'],['foreign','Auslandssachverhalt'],['none','Keine Umsatzsteuer / privat']],t.vat_treatment||'unknown')}${textarea('Steuerliche Begründung / offene Punkte','tax_note',t.tax_note,'maxlength=\"3000\"')}</details>`;
  const specialDetails=`<details class=\"context-details\"><summary>Besondere Angaben (nur bei Barzahlung, Video oder Geschäftsessen)</summary>${select('Ausgabentyp','expense_kind',expenseKindNames,t.expense_kind||'standard')}${detailWrap('cash-source-wrap',select('Bargeldquelle','cash_source',cashSourceNames,t.cash_source||'unknown'))}${detailWrap('video-purpose-wrap',textarea('Konkreter betrieblicher Zweck / Video','business_purpose',t.business_purpose||'','maxlength=\"2000\" placeholder=\"z. B. Zutaten und Requisiten für Video vom …\"'))}${`<div class=\"meal-details-wrap\"><div class=\"field-row\">${field('Ort der Bewirtung','meal_place',t.meal_place||'','text','maxlength=\"300\"')}${field('Anlass der Bewirtung','meal_occasion',t.meal_occasion||'','text','maxlength=\"1000\"')}</div>${textarea('Teilnehmer (Namen/Firma)','meal_participants',t.meal_participants||'','maxlength=\"2000\" placeholder=\"Alle teilnehmenden Personen/Firmen …\"')}</div>`}<p class=\"small muted cash-explanation\">Bei Bargeld: Beleg fotografieren/hochladen und Zweck festhalten. Eine private Zahlung ist keine private Ausgabe, wenn sie betrieblich veranlasst ist; eine spätere Erstattung darf nicht doppelt erfasst werden. Die KI entscheidet die Abziehbarkeit nicht automatisch.</p></details>`;
  $('.modal-body',form).insertAdjacentHTML('afterbegin',`${select('Zahlungsart','payment_method',paymentMethodNames,method)}${select('Bereich','scope',Object.entries(scopeNames),t.scope||'business')}${specialDetails}${advancedDetails}`);
  form.querySelector('[name=payment_method]')?.addEventListener('change',()=>syncPaymentDetails(form));
  form.querySelector('[name=expense_kind]')?.addEventListener('change',()=>syncPaymentDetails(form));
  form.querySelector('[name=scope]')?.addEventListener('change',()=>syncScopeDetails(form));
  syncPaymentDetails(form);addSaveState(form);
};
taskForm=function(...args){baseTaskForm(...args);addSaveState($('#task-form'));};
function factForm(id){const f=app.data.facts.find(x=>x.id===id)||{};showModal('Fakt mit Quelle festhalten',`<form id="fact-form" data-id="${id||''}"><div class="modal-body"><div class="form-result" role="alert"></div>${field('Fakt / Frage','title',f.title,'text','required')}${textarea('Angabe','value',f.value,'required maxlength="2000"')}${select('Gilt für das Arbeitsjahr','year',years(),f.year||app.year)}${select('Quelldokument','source_id',[['','Manuell belegte Angabe'],...app.data.documents.map(d=>[d.id,d.title])],f.source_id)}${textarea('Fundstelle / Herkunft','source_note',f.source_note,'required maxlength="1000"')}${select('Prüfstatus','status',[['open','Offen'],['confirmed','Von mir anhand der Quelle geprüft'],['superseded','Überholt']],f.status||'open')}</div><div class="modal-footer"><button class="btn primary" type="submit">Fakt speichern</button></div></form>`);addSaveState($('#fact-form'));}
function lawForm(id){const v=app.legal.versions.find(x=>x.id===id);showModal('Zeitliche Anwendbarkeit festhalten',`<form id="law-review-form" data-id="${id}"><div class="modal-body"><div class="form-result" role="alert"></div><p class="small settings-note">${esc(v.title)} · gespeichert ${stamp(v.retrieved_at)}. Das Abrufdatum allein belegt nicht die Gültigkeit. Bitte Übergangsregeln und Rechtsstand prüfen.</p><div class="field-row">${select('Ab Steuerjahr','valid_from',years(),v.valid_from||app.year)}${select('Bis Steuerjahr','valid_to',years(),v.valid_to||app.year)}</div>${textarea('Fundstelle und Begründung','review_note',v.review_note,'required minlength="10" maxlength="3000"')}</div><div class="modal-footer"><button class="btn primary" type="submit">Datierung festhalten</button></div></form>`);}

function draftKey(form){return form.dataset.draftKey||form.id+':'+(form.dataset.id||'new')+(['chat-form','profile-form'].includes(form.id)?':'+(form.dataset.year||app.year):'');}
async function collectForm(form,includeFile=true){const data=Object.fromEntries(new FormData(form));for(const el of form.elements){if(el.name&&el.type==='checkbox')data[el.name]=el.checked;if(el.name&&el.tagName==='SELECT'&&el.multiple)data[el.name]=[...el.selectedOptions].map(x=>x.value);}
 if(includeFile&&form.id==='document-form'){const file=form._file||app.pendingFile,recovered=form._recoveredFile||app.recoveredFile;if(file){if(file.size>20*1024*1024)throw new Error('Die Datei ist größer als 20 MB.');data.filename=file.name;data.file_base64=await fileBase64(file);}else if(recovered){data.filename=recovered.filename;data.file_base64=recovered.file_base64;}}
 if(includeFile&&['transaction-form','evidence-form'].includes(form.id)){const file=form._receiptFile||app.transactionReceiptFile,recovered=form._recoveredReceiptFile||app.recoveredReceiptFile;if(file){if(file.size>20*1024*1024)throw new Error('Die Datei ist größer als 20 MB.');data.receipt_filename=file.name;data.receipt_title=data.title||file.name;data.receipt_file_base64=await fileBase64(file);}else if(recovered){data.receipt_filename=recovered.filename;data.receipt_title=data.title||recovered.filename;data.receipt_file_base64=recovered.file_base64;}}
 return data;}
const draftable=new Set(['evidence-form','document-form','transaction-form','task-form','fact-form','chat-form','profile-form','ai-form','move-form','backup-settings-form','legal-settings-form']);
function queueDraft(form){if(!form||!draftable.has(form.id)||app.suppressDraft)return Promise.resolve();const key=draftKey(form),id=form.dataset.id||'',year=Number(form.dataset.year)||app.year,requestId=form.dataset.requestId||'';const revision=app.draftRevision;const pending=collectForm(form);const label=$('.save-state',form);if(label)label.textContent='Entwurf wird gespeichert …';
 const job=app.draftQueue.catch(()=>{}).then(async()=>{const payload=await pending;await api('/api/drafts',{key,payload:{...payload,__form:form.id,__id:id,__year:year,__request_id:requestId}});if(label)label.textContent='Entwurf gespeichert · '+new Date().toLocaleTimeString('de-DE');if(revision===app.draftRevision)app.unsavedDraft=false;});
 app.draftQueue=job.catch(e=>{app.unsavedDraft=true;if(label)label.textContent='Nicht gespeichert: '+e.message;toast('Entwurf nicht gesichert: '+e.message,true);});return app.draftQueue;}
closeModal=function(){if(!app.suppressDraft)queueDraft($('#modal form'));baseClose();app.recoveredFile=null;app.recoveredReceiptFile=null;};
async function removeDraft(form){await app.draftQueue;await api('/api/drafts',{key:draftKey(form),payload:{},delete:true});}
async function resumeDraft(key){const all=await api('/api/drafts'),d=all.find(x=>x.key===key);if(!d)return toast('Dieser Entwurf wurde bereits übernommen.');const p=d.payload;app.year=Number(p.__year)||app.year;
 const opening={'evidence-form':()=>evidenceForm(p.__id),'document-form':()=>documentForm(p.__id||null),'transaction-form':()=>transactionForm(p.__id||null),'task-form':()=>taskForm(p.__id||null),'fact-form':()=>factForm(p.__id||null),'chat-form':()=>navigate('chat'),'backup-settings-form':()=>navigate('safety')};(opening[p.__form]||(()=>navigate('settings')))();const form=$('#'+p.__form);if(!form)return toast('Formular für diesen Entwurf nicht verfügbar.',true);
 for(const el of form.elements){if(!el.name||!(el.name in p))continue;if(el.type==='checkbox')el.checked=!!p[el.name];else if(el.tagName==='SELECT'&&el.multiple)[...el.options].forEach(o=>o.selected=(p[el.name]||[]).includes(o.value));else if(el.type!=='file')el.value=p[el.name];}
 if(form.id==='transaction-form'){form.querySelector('[name=payment_method]')?.dispatchEvent(new Event('change',{bubbles:true}));syncPaymentDetails(form);}
 for(let parent=form.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
 form.dataset.draftKey=key;form.dataset.requestId=p.__request_id||'';if(p.file_base64){app.recoveredFile={filename:p.filename,file_base64:p.file_base64};form._recoveredFile=app.recoveredFile;$('#file-label').textContent=p.filename+' · Datei aus gespeichertem Entwurf';}if(p.receipt_file_base64){app.recoveredReceiptFile={filename:p.receipt_filename,file_base64:p.receipt_file_base64};form._recoveredReceiptFile=app.recoveredReceiptFile;const label=$('#transaction-receipt-label');if(label)label.textContent=p.receipt_filename+' · Datei aus gespeichertem Entwurf';}addSaveState(form);const label=$('.save-state',form);if(label)label.textContent='Entwurf wiederhergestellt · '+stamp(d.updated_at);toast('Entwurf wiederhergestellt.');}

action=async function(name,el){switch(name){
 case 'cited-source':{const source=el.dataset.source,type=source.slice(0,1),id=source.slice(2);if(type==='P'){app.year=Number(id);return navigate('settings');}if(type==='C')return navigate('assessments');const list={T:app.data.transactions,D:app.data.documents,F:app.data.facts,K:app.data.tasks}[type]||[];if(!list.some(x=>x.id===id))return toast('Diese Quelle ist nicht mehr in der Arbeitsansicht verfügbar. Bitte neu fragen.',true);return {T:transactionForm,D:documentDetail,F:factForm,K:taskForm}[type](id);}
 case 'import-assessments':{el.disabled=true;try{await api('/api/assessments/import',{});await refresh();toast('Bescheide, Angaben und Aufgaben in deiner Ablage gespeichert.');}finally{el.disabled=false;}return;}
 case 'scope-filter':app.scopeFilter=el.dataset.value;return render();
 case 'resume-draft':return resumeDraft(el.dataset.key);
 case 'seed-tasks':{const r=await api('/api/suggestions/add',{});await refresh();return toast(r.count?`${r.count} Aufgaben ergänzt. Umzug und Sicherung stehen unter 2026.`:'Die Startaufgaben sind bereits vorhanden.');}
 case 'snapshot':await api('/api/snapshot',{});toast('Sicherung wird erstellt und geprüft.');return pollStorage();
 case 'update-legal':await api('/api/legal/update',{});return loadLegal();
 case 'retry-legal':await api('/api/legal/update',{source_ids:[el.dataset.id]});return loadLegal();
 case 'retry-failed-legal':{const ids=(app.legal?.checks||[]).filter(c=>c.error).map(c=>c.source_id);if(ids.length)await api('/api/legal/update',{source_ids:ids});return loadLegal();}
 case 'profile-proposal':{const p=app.data.tax_profile_proposal,form=$('#profile-form');if(!p||Number(form?.dataset.year)!==p.year)return;for(const key of ['vat_status','filing_status','source_note'])form.elements[key].value=p[key];await queueDraft(form);return toast('2024-Angaben eingesetzt. Bitte prüfen und speichern.');}
 case 'review-law':return lawForm(el.dataset.id);
 case 'new-fact':return factForm();
 case 'edit-fact':return factForm(el.dataset.id);
 case 'chat-task':{const c=app.chatItems.find(c=>c.id===el.dataset.id),t=c.coordinator_json.tasks[Number(el.dataset.index)];return taskForm(null,{title:t.title,notes:t.reason+'\nKI-Vorschlag aus Gespräch '+c.id,year:c.year,due_confirmed:false});}
 case 'check-models':{el.disabled=true;try{const r=await api('/api/models');app.models=r.models;for(const name of ['worker_model','reviewer_model','coordinator_model']){const field=$(`[name="${name}"]`),current=field.value;field.innerHTML=options([...new Set([current,...r.models].filter(Boolean))],current);}const missing=['worker_model','reviewer_model','coordinator_model'].map(n=>$(`[name="${n}"]`).value).filter(n=>!r.models.includes(n));$('#model-status').textContent=missing.length?'Nicht gefunden: '+missing.join(', '):'Alle drei ausgewählten Modelle sind lokal vorhanden.';}catch(e){$('#model-status').textContent=e.message;}finally{el.disabled=false;}return;}
 default:return baseAction(name,el);}}
async function pollStorage(){await new Promise(r=>setTimeout(r,1500));const data=await api('/api/storage');app.data.storage=data;if(app.view==='safety')render();if(data.backup.state==='running')setTimeout(pollStorage,2000);else toast(data.backup.error||'Sicherung erstellt und geprüft.',!!data.backup.error);}

const originalAnalysisView=analysisView;
analysisView=function(a){if(a&&['running','queued'].includes(a.state))return `<p class="progress-label"><span class="spinner"></span>${esc(a.progress||'Drei Modelle prüfen nacheinander …')}</p>`;let html=originalAnalysisView(a);if(a?.state==='complete'&&a.coordinator_json)html+=`<section class="ai-reading"><h3>Koordinator · ${esc(a.coordinator_model)}</h3>${answerMarkup(a.coordinator_json)}${a.coordinator_json.questions?.length?`<ul>${a.coordinator_json.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`:''}</section>`;return html;};

submit=async function(form){const submitButton=$('[type="submit"]',form),result=$('.form-result',form);submitButton.disabled=true;form.inert=true;result.textContent='';result.className='form-result';
 try{clearTimeout(app.draftTimer);const data=await collectForm(form),id=form.dataset.id;let detail=null,keep=false;
   if(['document-form','transaction-form','task-form'].includes(form.id)){const type={'document-form':'documents','transaction-form':'transactions','task-form':'tasks'}[form.id];if(!id){form.dataset.requestId=form.dataset.requestId||crypto.randomUUID().replaceAll('-','');data.request_id=form.dataset.requestId;await queueDraft(form);}const r=await api('/api/'+type+(id?'/'+id:''),data,id?'PUT':'POST');if(type==='documents')detail=r.id;}
   else if(form.id==='chat-form'){await api('/api/chat',{...data,year:app.year,document_ids:data.document_ids||[],mode:'question'});app.chatYear=null;}
   else if(form.id==='evidence-form')await api('/api/evidence',{...data,id});
   else if(form.id==='profile-form')await api('/api/tax-profile',data);
   else if(form.id==='fact-form')await api('/api/facts',{...data,id:id||undefined});
   else if(form.id==='law-review-form'){await api('/api/legal/review',{...data,id});app.legal=null;}
   else if(form.id==='law-search-form'){const rows=await api('/api/legal/search?q='+encodeURIComponent(data.q)+'&year='+app.year);$('#law-results').innerHTML=rows.map(r=>`<article class="fact"><h3>${esc(r.title)}</h3><p class="document-text">${esc(r.body)}</p><p class="small">${r.year_checked?'Zeitliche Zuordnung erfasst':'Zeitliche Anwendbarkeit offen'} · ${esc(r.source_type)}</p></article>`).join('')||'<p>Keine passende Fundstelle im lokalen Archiv.</p>';keep=true;}
   else if(form.id==='restore-check-form'){const f=$('#restore-file').files[0];if(!f||f.size>20*1024*1024)throw new Error('Bitte eine Sicherung bis 20 MB auswählen. Größere Sicherungen über WIEDERHERSTELLEN_WINDOWS.bat prüfen.');const r=await api('/api/restore/check',{file_base64:await fileBase64(f)});result.textContent=`Prüfung bestanden: ${r.counts.documents} Dokumente, ${r.counts.transactions} Zahlungen, ${r.counts.tasks} Aufgaben. ${r.originals_checked} Originale unverändert.`;keep=true;}
   else await api('/api/settings',data);
   if(!keep){if(draftable.has(form.id))await removeDraft(form);app.suppressDraft=true;closeModal();app.suppressDraft=false;await refresh();const savedMessage=form.id==='transaction-form'&&data.receipt_file_base64?'Buchung und Beleg gespeichert.':'Gespeichert · '+new Date().toLocaleTimeString('de-DE');toast(savedMessage);if(detail)await documentDetail(detail);if(form.id==='chat-form')loadChat();}
 }catch(e){result.className='form-result form-error';result.textContent=e.message;}finally{submitButton.disabled=false;form.inert=false;app.suppressDraft=false;}}

function onDraftInput(event){const form=event.target.closest('form');if(!form||!draftable.has(form.id))return;if(form.id==='document-form'&&event.target.id==='document-file')form._file=app.pendingFile;if(['transaction-form','evidence-form'].includes(form.id)&&event.target.id==='transaction-receipt-file')form._receiptFile=app.transactionReceiptFile;app.draftRevision++;app.unsavedDraft=true;clearTimeout(app.draftTimer);app.draftTimer=setTimeout(()=>queueDraft(form),600);}
document.addEventListener('input',onDraftInput);document.addEventListener('change',onDraftInput);
$('#modal').addEventListener('cancel',()=>queueDraft($('#modal form')),true);
window.addEventListener('beforeunload',e=>{if(app.unsavedDraft){e.preventDefault();e.returnValue='';}});
